INSERT INTO blocs (cle, titre, contenu) VALUES
  ('accueil_apropos', 'Accueil — À propos de la bibliothèque', '<div class=\"what-we-do-wrap\">\r\n<div class=\"col-md-6 col-sm-6 col-xs-12 what-we-do\">\r\n<div class=\"clearfix margin-bottom-2\">\r\n<figure class=\"img-leading\"><img class=\"img-responsive\" src=\"{photo_apropos}\" alt=\"Salle de lecture de la bibliothèque universitaire universitaire\" /></figure>\r\n<div class=\"glow-wrap\"><i class=\"glow\"></i></div>\r\n</div>\r\n</div>\r\n<div class=\"col-md-6 col-sm-6 col-xs-12 what-we-do\">\r\n<p>&nbsp;</p>\r\n<h4 class=\"bordered-title\">Université de Kara</h4>\r\n<h1 class=\"leading\">La bibliothèque universitaire</h1>\r\n<p>La bibliothèque de l’Université de Kara met à disposition des étudiants, enseignants et chercheurs des ouvrages couvrant 8 grands domaines du savoir. Ce catalogue en ligne vous permet de retrouver rapidement un document, de connaître ses auteurs et de vérifier sa disponibilité avant de vous déplacer.</p>\r\n<div class=\"col-xs-12 col-lg-6 col-md-6\">\r\n<ul>\r\n<li><i class=\"fa fa-search\" aria-hidden=\"true\"> </i><a href=\"{base}/index.php/catalogue\">Catalogue en ligne</a></li>\r\n<li><i class=\"fa fa-th-large\" aria-hidden=\"true\"> </i><a href=\"{base}/index.php/domaines\">Classement par domaine</a></li>\r\n</ul>\r\n</div>\r\n<div class=\"col-xs-12 col-lg-6 col-md-6\">\r\n<ul>\r\n<li><i class=\"fa fa-tags\" aria-hidden=\"true\"> </i><a href=\"{base}/index.php/types\">Recherche par type</a></li>\r\n<li><i class=\"fa fa-users\" aria-hidden=\"true\"> </i><a href=\"{base}/index.php/auteurs\">Index des auteurs</a></li>\r\n</ul>\r\n</div>\r\n<div style=\"clear: both; margin-top: 20px;\" class=\"styled-text\">Prêt à domicile, consultation sur place et accompagnement dans vos recherches documentaires.</div>\r\n{recherche}\r\n<a href=\"{base}/index.php/catalogue\" class=\"tp-button red exeltis\" style=\"min-height: 0px; min-width: 0px; line-height: 27px; border-width: 0px; margin: 0px; padding: 15px; letter-spacing: 0px; font-size: 16px;\">PARCOURIR LE CATALOGUE</a></div>\r\n</div>'),
  ('accueil_types', 'Accueil — Introduction des types de documents', '<h4 class=\"bordered-title\">Types de documents</h4>\r\n<h1 class=\"leading\">Trouvez le bon type de document</h1>\r\n<p>Chaque ouvrage est classé selon sa nature. Choisissez un type pour afficher tous les documents correspondants, quel que soit leur domaine.</p>'),
  ('appel_contact', 'Accueil — Bandeau « Vous ne trouvez pas un ouvrage ? »', '<div class=\"reliable-company-wrap\">\r\n<div class=\"col-xs-12 col-md-9 col-sm-9  reliable-company\">\r\n<h1><span style=\"color: #ffffff;\">Vous ne trouvez pas un ouvrage ?</span></h1>\r\n<p><span style=\"color: #ffffff;\">Nos bibliothécaires vous aident dans vos recherches et peuvent proposer de nouvelles acquisitions.</span></p>\r\n</div>\r\n<div class=\"col-xs-12 col-md-3 col-sm-3  reliable-company\"><br /> <a href=\"{base}/index.php/contact\" class=\"btn bg-white exeltis\" style=\"min-height: 0px; min-width: 0px; line-height: 27px; border-width: 0px; margin: 0px; padding: 15px; letter-spacing: 0px; font-size: 16px;\">Nous contacter <i class=\"fa fa-long-arrow-right\" aria-hidden=\"true\"></i></a></div>\r\n<div style=\"clear: both;\"></div>\r\n</div>'),
  ('contact_infos', 'Page contact — Informations complémentaires', '<p>Horaires : du lundi au vendredi de 8h à 18h, le samedi de 9h à 13h.</p><p>Pour toute question sur un prêt, une réservation ou votre compte lecteur, utilisez le formulaire ci-dessous.</p>'),
  ('pied_copyright', 'Pied de page — Copyright', '<p>Copyright © 2026 Université de Kara — Bibliothèque universitaire — Tous droits réservés</p>'),
  ('pied_horaires', 'Pied de page — Horaires d’ouverture', '<ul class=\"biblio-horaires\">\r\n<li><strong>Lundi – Vendredi</strong> : 8h00 – 18h00</li>\r\n<li><strong>Samedi</strong> : 9h00 – 13h00</li>\r\n<li><strong>Dimanche</strong> : fermé</li>\r\n</ul>\r\n<p class=\"bottom-socialicons\" style=\"text-align: left;\"><span style=\"padding-right: 10px;\">Suivez-nous :</span> <a href=\"#\"><i class=\"fa fa-facebook\"> </i></a> <a href=\"#\"><i class=\"fa-brands fa-x-twitter\"> </i></a> <a href=\"#\"><i class=\"fa fa-youtube\"> </i></a> <a href=\"#\"><i class=\"fa fa-instagram\"> </i></a></p>'),
  ('pied_infos', 'Pied de page — Présentation et coordonnées', '<div>\r\n<p style=\"margin-bottom: 15px;\"><a href=\"{base}/index.php\"><img src=\"{base}/images/biblio/logo-blanc.png\" alt=\"Université de Kara\" width=\"220\" /></a></p>\r\n<p>Bibliothèque universitaire — catalogue en ligne des ouvrages : recherche par domaine, par type de document et par auteur.</p>\r\n<br />\r\n<p style=\"margin-bottom: 15px;\"><strong><i class=\"fa fa-phone\" aria-hidden=\"true\"></i>&nbsp; Téléphone :</strong> +000 00 00 00 00</p>\r\n<p style=\"margin-bottom: 15px;\"><strong><i class=\"fa fa-map-marker\" aria-hidden=\"true\"></i>&nbsp; Adresse :</strong> Campus universitaire, bâtiment central</p>\r\n<p style=\"margin-bottom: 15px;\"><strong><i class=\"fa fa-envelope\" aria-hidden=\"true\"></i>&nbsp; E-mail :</strong> <a href=\"mailto:contact@biblio.local\">contact@biblio.local</a></p>\r\n</div>');
REPLACE INTO reglages (cle, valeur) VALUES
  ('contact_adresse', 'Campus de l’Université de Kara'),
  ('contact_email', 'contact@biblio.local'),
  ('contact_nom', 'Bibliothèque universitaire de Kara'),
  ('contact_pays', 'Togo'),
  ('contact_role', 'Université de Kara — Accueil, prêts et renseignements'),
  ('contact_telephone', '+228 00 00 00 00'),
  ('contact_ville', 'Kara'),
  ('site_description', 'Bibliothèque de l’Université de Kara : catalogue en ligne des ouvrages, recherche par domaine, par type de document et par auteur.'),
